    ret_val = []

    if hasattr(obj_iter, 'all'):
        obj_iter = obj_iter.all()

    try:
        iter(obj_iter)
    except TypeError:
        obj_iter = [obj_iter]

    for obj in obj_iter:
        rel_objs = []
        for part in path:
            if not part:
